const temperature = Math.round($json.temperature);
const tempMin = typeof $json.tempMin === 'number' && Number.isFinite($json.tempMin) ? Math.round($json.tempMin) : null;
const tempMax = typeof $json.tempMax === 'number' && Number.isFinite($json.tempMax) ? Math.round($json.tempMax) : null;
const range = tempMin !== null && tempMax !== null && tempMin <= temperature && tempMax >= temperature
  ? ` Mínima atual na área: ${tempMin}°C | Máxima atual na área: ${tempMax}°C.` : '';
return [{json: {city: $json.city, temperature, tempMin, tempMax, range,
  message: `🌤️ A temperatura em ${$json.city} é de ${temperature}°C.${range}`,
  ok: true, useGemini: false}}];

const fallback = $('Fallback determinístico').first().json;
let candidate = null;
try {
  if (!$json.error) {
    let text = $json.candidates?.[0]?.content?.parts?.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('')
      ?? $json.content?.parts?.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('');
    if (typeof text === 'string' && text.trim()) {
      text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
      candidate = JSON.parse(text);
    }
  }
} catch { candidate = null; }
const message = candidate?.message;
const numbers = typeof message === 'string' ? message.match(/-?\d+(?:[.,]\d+)?/g) : [];
const expected = fallback.range ? [fallback.temperature, fallback.tempMin, fallback.tempMax] : [fallback.temperature];
const valid = candidate?.ok === true && typeof message === 'string' && message.length <= 280 && message.trim().length > 0
  && !/[\r\n<>]/.test(message)
  && message.toLocaleLowerCase('pt-BR').includes(fallback.city.toLocaleLowerCase('pt-BR'))
  && message.includes(`${fallback.temperature}°C`)
  && (!fallback.range || message.endsWith(fallback.range))
  && numbers?.length === expected.length && numbers.every((n, i) => Number(n) === expected[i]);
return [{json: {message: valid ? message.trim() : fallback.message, ok: true, source: valid ? 'gemini' : 'fallback'}}];

const text = typeof $json.message?.text === 'string' ? $json.message.text : '';
const parts = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().split(',').map(s => s.trim().replace(/\s+/g, ' '));
const ufs = 'ac al ap am ba ce df es go ma mt ms mg pa pb pr pe pi rj rn rs ro rr sc sp se to'.split(' ');
const valid = (parts.length === 2 || parts.length === 3) && /^[a-z][a-z .'-]*$/.test(parts[0]) && ufs.includes(parts[1]) && (parts.length === 2 || parts[2] === 'br');
return [{json: {queue: valid ? `${parts[0]},${parts[1]},br` : '', valid, chatId: $json.message?.chat?.id}}];

let body = $json.body ?? $json.data;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = null;
  }
}

const ok =
  Number($json.statusCode) >= 200 &&
  Number($json.statusCode) < 300 &&
  Number(body?.cod) === 200 &&
  typeof body?.name === 'string' &&
  body.name.trim().length > 0 &&
  typeof body?.main?.temp === 'number' &&
  Number.isFinite(body.main.temp) &&
  body?.sys?.country === 'BR';

return [{
  json: {
    ok,
    city: ok ? body.name : '',
    temperature: ok ? body.main.temp : null,
    tempMin: ok && typeof body.main.temp_min === 'number' && Number.isFinite(body.main.temp_min) ? body.main.temp_min : null,
    tempMax: ok && typeof body.main.temp_max === 'number' && Number.isFinite(body.main.temp_max) ? body.main.temp_max : null
  }
}];
